#include "modding.h"
#include "recompconfig.h"

typedef signed int s32;
typedef unsigned char u8;

// Save data base — all in-game flags and counters live here.
extern u8 D_8015C608_15D208[];

// Offsets of the fish counters (s32) within the save data block.
#define SAVE_BLUE_FISH_COUNT 0x118
#define SAVE_YELLOW_FISH_COUNT 0x114
#define SAVE_RED_FISH_COUNT 0x110

// Quest-phase flags: set by Ushiwaka when he asks for each fish type.
#define FLAG_LOOKING_BLUE_FISH 0x02C
#define FLAG_LOOKING_YELLOW_FISH 0x02B
#define FLAG_LOOKING_RED_FISH 0x02A

// The counts the original Ushiwaka scenario script checks for (SNE opcodes).
// When a fish counter equals these values the quest advances to the next stage.
#define BLUE_FISH_MAX 3
#define YELLOW_FISH_MAX 5
#define RED_FISH_MAX 8

#define READ_FISH(offset) (*(s32 *)(D_8015C608_15D208 + (offset)))
#define WRITE_FISH(offset, value) (*(s32 *)(D_8015C608_15D208 + (offset)) = (value))

// Flags are stored as a flat bit-array inside the save block at byte (flag_id / 8),
// bit (flag_id % 8).
#define IS_FLAG_SET(id) \
    ((*(u8 *)(D_8015C608_15D208 + ((id) / 8)) & (1u << ((id) % 8))) != 0)

// Hook into a frequently-called game function so we can watch fish counts every
// frame.  When the relevant quest flag is active and the player has caught at
// least as many fish as the configured threshold, the counter is bumped up to the
// value the Ushiwaka scenario expects, allowing the quest stage to complete.
RECOMP_HOOK("func_80002040_2C40")
void fish_quest_threshold_hook(void)
{
    if (IS_FLAG_SET(FLAG_LOOKING_BLUE_FISH))
    {
        s32 count = READ_FISH(SAVE_BLUE_FISH_COUNT);
        s32 required = (s32)recomp_get_config_u32("blue_fish_required");
        if (count >= required && count < BLUE_FISH_MAX)
        {
            WRITE_FISH(SAVE_BLUE_FISH_COUNT, BLUE_FISH_MAX);
        }
    }

    if (IS_FLAG_SET(FLAG_LOOKING_YELLOW_FISH))
    {
        s32 count = READ_FISH(SAVE_YELLOW_FISH_COUNT);
        s32 required = (s32)recomp_get_config_u32("yellow_fish_required");
        if (count >= required && count < YELLOW_FISH_MAX)
        {
            WRITE_FISH(SAVE_YELLOW_FISH_COUNT, YELLOW_FISH_MAX);
        }
    }

    if (IS_FLAG_SET(FLAG_LOOKING_RED_FISH))
    {
        s32 count = READ_FISH(SAVE_RED_FISH_COUNT);
        s32 required = (s32)recomp_get_config_u32("red_fish_required");
        if (count >= required && count < RED_FISH_MAX)
        {
            WRITE_FISH(SAVE_RED_FISH_COUNT, RED_FISH_MAX);
        }
    }
}

mnsg-enable-boss-rush/src/impact_boss_ru.content:
#include "modding.h"

#define OPTIONS_MENU_STATE_OFFSET 0x78
#define OPTIONS_MENU_BUILD_LOCKED 1
#define OPTIONS_MENU_BUILD_WITH_BOSS_RUSH 6

/*
 * US file-select overlay (.file_15, ROM 0x65E310).
 * func_801D21B8_665068 state 0 checks D_8015CC18_15D818 (saved unlock)
 * and 0x8015C564 (session unlock), then chooses state 1 or state 6.
 * State 6 builds the native "Consecutive Fighting! Large Boss" option;
 * its selection handler enters the boss rush through func_800370B0_37CB0.
 *
 * Redirect only the locked menu builder. Keep state 0's initialization,
 * native navigation/launch, and Sound Mode's return path intact. Neither
 * the save data nor either unlock flag is modified.
 */
RECOMP_HOOK("func_801D21B8_665068")
void enable_boss_rush_menu_hook(void *task)
{
    unsigned char *state = (unsigned char *)task + OPTIONS_MENU_STATE_OFFSET;

    if (*state == OPTIONS_MENU_BUILD_LOCKED)
    {
        *state = OPTIONS_MENU_BUILD_WITH_BOSS_RUSH;
    }
}

