#define ACTOR_CAP_TOTAL (*(volatile int *)0x8015CCFC)
#define ACTOR_CAP_KIND_8 (*(volatile int *)0x8015CCE0)
#define ACTOR_CAP_KIND_9 (*(volatile int *)0x8015CCF0)
#define ACTOR_CAP_KIND_10 (*(volatile int *)0x8015CCE4)
#define ACTOR_CAP_KIND_6 (*(volatile int *)0x8015CCE8)
#define ACTOR_CAP_KIND_12 (*(volatile int *)0x8015CCEC)
#define DUPLICATE_RANDOM_RADIUS 50

static int s_duplicate_enemy_guard;
static unsigned int s_duplicate_position_rng = 0xA341316Cu;

static int configured_enemy_multiplier(void)
{
    unsigned long option = recomp_get_config_u32("enemy_multiplier");

    if (option > 2)
        return 1;
    return (int)option + 1;
}

static void raise_enemy_actor_caps(void)
{
    if (ACTOR_CAP_TOTAL < 0x78)
        ACTOR_CAP_TOTAL = 0x78;
    if (ACTOR_CAP_KIND_8 < 0x40)
        ACTOR_CAP_KIND_8 = 0x40;
    if (ACTOR_CAP_KIND_9 < 0x40)
        ACTOR_CAP_KIND_9 = 0x40;
    if (ACTOR_CAP_KIND_10 < 0x30)
        ACTOR_CAP_KIND_10 = 0x30;
    if (ACTOR_CAP_KIND_6 < 0x40)
        ACTOR_CAP_KIND_6 = 0x40;
    if (ACTOR_CAP_KIND_12 < 0x10)
        ACTOR_CAP_KIND_12 = 0x10;
}

static int is_enemy_actor_id(unsigned short actor_id)
{
    switch (actor_id)
    {
    case 0x0CB: /* Ghost Robot Tsurami */
    case 0x0FA: /* Robot Bee */
    case 0x0FB: /* Pink Robot FB */
    case 0x0FC: /* Pink Robot FC */
    case 0x0FD: /* Green Robot FD */
    case 0x0FE: /* Green Robot FE */
    case 0x0FF: /* Big Swatting Robot */
    case 0x100: /* Blue Robot */
    case 0x103: /* Scarecrow Bot */
    case 0x104: /* Can-can Legs */
    case 0x105: /* Flatfish */
    case 0x106: /* Helicopter Kite */
    case 0x107: /* Bamboo Shooter */
    case 0x108: /* Jet Robot */
    case 0x109: /* Yellow Robot */
    case 0x10A: /* Big Swatting Robot Red */
    case 0x10B: /* Shrinking Robot */
    case 0x10C: /* Sword Robot */
    case 0x110: /* Pink Robot 110 */
    case 0x12C: /* Small Cannon */
    case 0x12D: /* Flying Dragon Head */
    case 0x12E: /* Seahorse */
    case 0x12F: /* Spiny Sea Urchin */
    case 0x130: /* Drum Robot */
    case 0x131: /* Triangle Robot */
    case 0x133: /* Paper Ghost */
    case 0x136: /* Red Eye Fish */
    case 0x13A: /* Tank */
    case 0x13B: /* Spiny Sea Urchin (Kii-Awaji) */
    case 0x13C: /* Giant Enemy Crab */
    case 0x13D: /* Samurai */
    case 0x13E: /* Rose Robot */
    case 0x13F: /* Hammer Thrower */
    case 0x140: /* Fire Stalker */
    case 0x141: /* Ninja */
    case 0x144: /* Burrowing Robot */
    case 0x145: /* Kite */
    case 0x147: /* Bomber Bird */
    case 0x148: /* Water Snake */
    case 0x190: /* Flying Tile */
    case 0x191: /* Unknown in vanilla export */
    case 0x198: /* Spike Chain */
    case 0x19A: /* Falling Barrel */
    case 0x19D: /* Slicer */
    case 0x1A6: /* Fox Mask */
    case 0x1A9: /* Falling Bomb Block */
    case 0x1AA: /* Jump Rope */
    case 0x1B0: /* Mind-Control Robot */
    case 0x1B6: /* Robot Bee Spawner */
    case 0x2F6: /* Chef */
    case 0x334: /* Sushi Spawner */
    case 0x362: /* Unknown in vanilla export */
    case 0x365: /* Giant Spinning Top */
    case 0x3CA: /* Spike Floor */
    case 0x3D1: /* Floating Ingredients */
    case 0x3DA: /* Boulder */
    case 0x3EF: /* Spiny Urchin Spawner */
    case 0x3FC: /* Floor Flamethrower */
        return 1;
    default:
        return 0;
    }
}

static short offset_coord(short value, short offset)
{
    int result = (int)value + (int)offset;

    if (result > 32767)
        return 32767;
    if (result < -32768)
        return -32768;
    return (short)result;
}

static unsigned int next_duplicate_random(void)
{
    s_duplicate_position_rng =
        s_duplicate_position_rng * 1664525u + 1013904223u;
    return s_duplicate_position_rng;
}

static short random_axis_offset(void)
{
    return (short)((int)(next_duplicate_random() %
                         (DUPLICATE_RANDOM_RADIUS * 2 + 1)) -
                   DUPLICATE_RANDOM_RADIUS);
}

static void random_duplicate_offsets(short *x_offset, short *z_offset)
{
    int attempt;
    int x;
    int z;

    for (attempt = 0; attempt < 8; attempt++)
    {
        x = random_axis_offset();
        z = random_axis_offset();
        if ((x != 0 || z != 0) &&
            x * x + z * z <=
                DUPLICATE_RANDOM_RADIUS * DUPLICATE_RANDOM_RADIUS)
        {
            *x_offset = (short)x;
            *z_offset = (short)z;
            return;
        }
    }

    *x_offset = (short)((int)(next_duplicate_random() %
                              (DUPLICATE_RANDOM_RADIUS * 2 + 1)) -
                        DUPLICATE_RANDOM_RADIUS);
    *z_offset = 0;
    if (*x_offset == 0)
        *x_offset = DUPLICATE_RANDOM_RADIUS;
}

RECOMP_HOOK("func_80218A54_5D3F24")
void extra_options_enemy_multiplier_spawn_hook(
    int actor, ExtraOptionsActorInstance *instance)
{
    ExtraOptionsActorInstance duplicate_instance;
    ExtraOptionsActorDefinition *definition;
    unsigned short actor_id;
    unsigned char actor_type;
    short model_id;
    int *owner;
    int duplicate;
    int multiplier;
    int duplicate_index;
    short base_x;
    short base_z;
    short x_offset;
    short z_offset;
    float scale;

    multiplier = configured_enemy_multiplier();
    if (s_duplicate_enemy_guard || multiplier <= 1 ||
        !extra_options_save_is_loaded() || !instance)
        return;

    definition = D_8015CDE0;
    if (D_8015CDDC != instance || !definition)
        return;

    actor_id = definition->actor_id;
    if (!is_enemy_actor_id(actor_id))
        return;

    raise_enemy_actor_caps();
    actor_type = D_802297D6_5E4CA6[actor_id + 0x80D];
    model_id = *(short *)&D_802297D6_5E4CA6[actor_id * 2];
    scale = D_80239AFC_5F4FCC;
    base_x = instance->position.x;
    base_z = instance->position.z;

    for (duplicate_index = 1; duplicate_index < multiplier;
         duplicate_index++)
    {
        owner = func_80219CA0_5D5170(0, actor_type);
        if (!owner)
            return;

        duplicate = func_8003555C_3615C(
            owner, D_802287BC_5E3C8C[actor_id], 0, 0xC006D920,
            0, 0, 0, 0, 0, 0, scale, scale, scale, 0, 0, model_id);
        if (!duplicate)
            return;

        duplicate_instance = *instance;
        random_duplicate_offsets(&x_offset, &z_offset);
        duplicate_instance.position.x = offset_coord(base_x, x_offset);
        duplicate_instance.position.z = offset_coord(base_z, z_offset);
        base_x = duplicate_instance.position.x;
        base_z = duplicate_instance.position.z;

        s_duplicate_enemy_guard = 1;
        func_80218A54_5D3F24(duplicate, &duplicate_instance);
        s_duplicate_enemy_guard = 0;
    }
}

mnsg-extra-options/src/hyper_congo.c.content:
#include "modding.h"
#include "extra_options.h"
#include "hyper_enemies.h"
#include "recompconfig.h"
#include "recomputils.h"

/* Congo's actor initializer replaces the common func_80218F30 task +0x10
 * post callback with func_0800000C.  Keep his exact root and liveness
 * checks here while reusing Hyper Enemies' single guarded replay loop. */

#define TASK_OBJECT(task) \
    (*(void *volatile *)((char *)(task) + 0x18))
#define TASK_ACTOR_ID(task) \
    (*(volatile unsigned short *)((char *)(task) + 0x5C))
#define TASK_ENTITY_ID(task) \
    (*(volatile unsigned short *)((char *)(task) + 0x5E))
#define TASK_STATUS(task) \
    (*(volatile unsigned int *)((char *)(task) + 0x68))
#define TASK_GENERATION(task) \
    (*(volatile unsigned char *)((char *)(task) + 0x74))
#define TASK_HEALTH(task) \
    (*(volatile unsigned char *)((char *)(task) + 0x8D))
#define TASK_OWNER(task) \
    (*(void *volatile *)((char *)(task) + 0xD0))
#define TASK_PART_OWNER(task) \
    (*(void *volatile *)((char *)(task) + 0xDC))
#define TASK_CONGO_FLAGS(task) \
    (*(volatile unsigned int *)((char *)(task) + 0xE8))
#define TASK_RESOURCE_ID(task) \
    (*(volatile unsigned short *)((char *)(task) + 0x28))
#define TASK_RESOURCE(task) \
    (*(void *volatile *)((char *)(task) + 0x2C))
#define TASK_SPIN_TIMER(task) \
    (*(volatile unsigned short *)((char *)(task) + 0x8A))
#define OBJECT_YAW(object) \
    (*(volatile unsigned short *)((char *)(object) + 0x16))

#define TASK_STATUS_REMOVE_PENDING 0x00000002u

#define ENTITY_CONGO 0x0323u
#define ENTITY_CONGO_FLAME 0x007Eu
#define CONGO_FLAME_CAPACITY 32u
#define CONGO_HEALTH_CONTROLLER 0x04000000u
#define CONGO_PART_COUNT 6u
#define CONGO_HYPER_SPIN_ROTATIONS 4u
#define CONGO_SPIN_END_YAW 0x0360u
#define CONGO_SPIN_ANIMATION_BASE 12u
#define CONGO_DAMAGE_EVENT 0x0Bu
#define TASK_CALLBACK_DISABLED_BIT 0x00800000u

typedef void (*HyperCongoTaskCallback)(void *task, void *object);

/* Host tests substitute this callback ABI: slots are four bytes apart, and
 * the disabled bit belongs to game addresses, not 64-bit host addresses. */
#ifndef CONGO_TASK_AI
#define CONGO_TASK_AI(task) \
    (*(HyperCongoTaskCallback volatile *)((char *)(task) + 0x0C))
#endif
#ifndef CONGO_TASK_POST
#define CONGO_TASK_POST(task) \
    (*(HyperCongoTaskCallback volatile *)((char *)(task) + 0x10))
#endif
#ifndef CONGO_CALLBACK_IS_ENABLED
#define CONGO_CALLBACK_IS_ENABLED(callback) \
    ((callback) && (((unsigned long)(callback) & TASK_CALLBACK_DISABLED_BIT) == 0))
#endif

typedef struct
{
    void *task;
    void *object;
    unsigned short actor_id;
    unsigned char generation;
    unsigned char padding;
} HyperCongoIdentity;

extern unsigned short D_800C7AB2;
extern unsigned char *D_8015C5C8_15D1C8;
extern void *D_8016DAB4_16E6B4;
extern void *func_8021DDE8_5D92B8(
    void *owner, HyperCongoTaskCallback initializer, unsigned char task_kind,
    float x, float y, float z, int angle);
extern void *func_800141C4_14DC4(unsigned int file_id);
extern void func_80023E40_24A40(unsigned int event);
extern void func_8003521C_35E1C(HyperCongoTaskCallback callback);
extern void func_8021664C_5D1B1C(
    void *task, unsigned int animation, float rate, unsigned int flags);
extern void func_08000DCC_6B406C(void *task, void *object);
extern void func_08007BB0_6BAE50(void *task, void *object);
extern void func_08007C18_6BAEB8(void *task, void *object);

static HyperCongoIdentity s_tracked_congo;
static unsigned short s_runtime_room;
static unsigned char s_runtime_active;
static unsigned char s_replay_reported;
static unsigned char s_defeated;
static unsigned char s_breath_clock_active;
static unsigned char s_breath_phase;
static HyperCongoIdentity s_flames[CONGO_FLAME_CAPACITY];
static unsigned int s_next_flame;
static HyperCongoIdentity s_parts[CONGO_PART_COUNT];
static unsigned char s_spin_rotations;
static unsigned char s_spin_active;
static unsigned char s_spin_trigger_consumed;
static unsigned char s_spin_trigger_health;

static void restart_congo_spin_parts(void *root);

static void clear_congo_spin_state(void)
{
    s_spin_rotations = 0;
    s_spin_active = 0;
    s_spin_trigger_consumed = 0;
    s_spin_trigger_health = 0;
}

static void clear_congo_tracking(void)
{
    unsigned int index;

    s_tracked_congo.task = 0;
    s_replay_reported = 0;
    s_defeated = 0;
    s_breath_clock_active = 0;
    clear_congo_spin_state();
    s_next_flame = 0;
    for (index = 0; index < CONGO_FLAME_CAPACITY; index++)
        s_flames[index].task = 0;
    for (index = 0; index < CONGO_PART_COUNT; index++)
        s_parts[index].task = 0;
}

static int hyper_congo_is_enabled(void)
{
    return recomp_get_config_u32("hyper_enemies") == 0;
}

static int refresh_congo_runtime_state(void)
{
    if (!extra_options_save_is_loaded())
    {
        if (s_runtime_active)
            clear_congo_tracking();
        s_runtime_active = 0;
        return 0;
    }

    if (!s_runtime_active || s_runtime_room != D_800C7AB2)
    {
        clear_congo_tracking();
        s_runtime_room = D_800C7AB2;
        s_runtime_active = 1;
    }
    return 1;
}

static int identity_matches(const HyperCongoIdentity *identity, void *task)
{
    return identity->task == task && task &&
           identity->object == TASK_OBJECT(task) &&
           identity->actor_id == TASK_ACTOR_ID(task) &&
           identity->generation == TASK_GENERATION(task);
}

static void bind_identity(HyperCongoIdentity *identity, void *task)
{
    identity->task = task;
    identity->object = TASK_OBJECT(task);
    identity->actor_id = TASK_ACTOR_ID(task);
    identity->generation = TASK_GENERATION(task);
}

static int hyper_congo_is_live(void *task)
{
    /* A228 plus entity 0x323 identifies the native boss.  Bind his actual
     * room and invalidate on transitions instead of guessing it from a
     * debug teleport destination (0x01A precedes the fight in room 0x016). */
    return refresh_congo_runtime_state() && task &&
           !s_defeated && identity_matches(&s_tracked_congo, task) &&
           TASK_ENTITY_ID(task) == ENTITY_CONGO &&
           (TASK_STATUS(task) & TASK_STATUS_REMOVE_PENDING) == 0 &&
           TASK_HEALTH(task) > 0;
}

/* A228 is Congo's exact health-bearing root callback.  His animation parts
 * and flames are tracked separately through their own native constructors. */
RECOMP_HOOK("func_0800A228_6BD4C8")
void extra_options_track_hyper_congo(void *actor)
{
    void *object;

    if (!actor || TASK_ENTITY_ID(actor) != ENTITY_CONGO ||
        !refresh_congo_runtime_state())
    {
        return;
    }

    object = TASK_OBJECT(actor);
    if (!object)
        return;

    if (!identity_matches(&s_tracked_congo, actor))
    {
        clear_congo_tracking();
        recomp_printf("[Extra Options] Congo tracked: room=0x%03X, Hyper Enemies=%s.\n",
                      (unsigned int)D_800C7AB2,
                      hyper_congo_is_enabled()
                          ? "enabled" : "disabled");
    }

    bind_identity(&s_tracked_congo, actor);

    /* A228 restores HP to one before scheduling the victory sequence.
