        TASK_ACTOR_ID(task) != ACTOR_DARUMANYO ||
        (TASK_STATUS(task) & TASK_STATUS_REMOVE_PENDING) != 0 ||
        DHARUMANYO_TASK_POST(task) != func_08003810_6CBA20)
