    unsigned int extra_tick;
    unsigned short room;
    void *saved_current_task;
    void *task;

    if (s_replay_guard || !hyper_enemies_is_enabled() ||
        !refresh_runtime_state() || !thaisamba_special_boss_is_live())
    {
        return;
