    if (s_replay_guard)
        return;

    s_capture_valid = 0;
    s_captured_post_callback = 0;
    if (!target_is_live || !hyper_enemies_is_enabled() ||
        !refresh_runtime_state() ||
        task != D_8016DAB4_16E6B4 ||
        !target_is_live(task))
    {
