    resource = func_800141C4_14DC4(RYO_POPUP_FILE_ID);
    if (!is_loaded_resource(resource))
        return;

    func_8000F420_10020(0x2B2, D_8020CBF0_5C8B00,
                        player_object, 400.0f);

    popup_task = func_802171A8_5D2678(
        owner, extra_options_ryo_popup_initialize, RYO_POPUP_TASK_KIND);
    if (!is_rdram_pointer(popup_task))
        return;

    /* The initializer runs on the next task update, after these are set. */
    TASK_WRITE16(popup_task, 0x28, RYO_POPUP_FILE_ID);
    TASK_WRITE32(popup_task, 0x2C, resource);
}

/* Normal stage resources have finished loading when this hook runs. Load the
 * small native robbery-effect file into the same scene registry it expects. */
RECOMP_HOOK_RETURN("func_8020D6BC_5C8B8C")
void extra_options_load_ryo_popup_resource(void)
{
    void *resource;

    if (!loose_ryo_on_hit_is_enabled())
        return;

    resource = func_800141C4_14DC4(RYO_POPUP_FILE_ID);
    if (!is_loaded_resource(resource))
        func_80013B14_14714(RYO_POPUP_FILE_ID);
}

/* Ghidra shows every applied player-damage path passing a negative signed
 * delta through this HP adjuster. Healing is positive and is ignored. */
RECOMP_HOOK("func_801DCD48_598C58")
void extra_options_loose_ryo_on_hit_hook(signed char hp_delta)
{
    if (hp_delta >= 0 || !loose_ryo_on_hit_is_enabled() ||
        !extra_options_save_is_loaded() || CURRENT_HP_READ() == 0)
    {
        return;
    }

    func_801DCCF0_598C00(RYO_LOSS_PER_HIT);
    spawn_ryo_loss_popup();
}

mnsg-extra-options/src/no_hit.c.content:
#include "modding.h"
#include "extra_options.h"
#include "recompconfig.h"

#define CURRENT_HP_OFFSET (-0x21)
#define CURRENT_HP_READ() \
    (*(volatile unsigned char *)((char *)D_8015C608_15D208 + CURRENT_HP_OFFSET))
#define CURRENT_HP_WRITE(value) \
    (*(volatile unsigned char *)((char *)D_8015C608_15D208 + CURRENT_HP_OFFSET) = \
         (unsigned char)(value))
#define CURRENT_CHARACTER_READ() \
    ((*(volatile unsigned int *)0x8015C5DC) & 0xFFu)

static unsigned char s_previous_hp;
static unsigned int s_previous_character;
static int s_hp_tracking_initialized;

static int no_hit_is_enabled(void)
{
    /* Enabled is the first enum entry in mod.toml, so its value is zero. */
    return recomp_get_config_u32("no_hit") == 0;
}

static void reset_hp_tracking(void)
{
    s_previous_hp = 0;
    s_previous_character = 0;
    s_hp_tracking_initialized = 0;
}

RECOMP_HOOK_RETURN("func_80002040_2C40")
void extra_options_no_hit_frame_hook(void)
{
    unsigned char current_hp;
    unsigned int current_character;

    if (!extra_options_save_is_loaded())
    {
        reset_hp_tracking();
        return;
    }

    current_hp = CURRENT_HP_READ();
    current_character = CURRENT_CHARACTER_READ();

    if (!s_hp_tracking_initialized ||
        current_character != s_previous_character)
    {
        s_previous_hp = current_hp;
        s_previous_character = current_character;
        s_hp_tracking_initialized = 1;
        return;
    }

    if (no_hit_is_enabled() &&
        current_hp < s_previous_hp && current_hp > 0)
    {
        CURRENT_HP_WRITE(0);
        current_hp = 0;
    }

    s_previous_hp = current_hp;
    s_previous_character = current_character;
}

mnsg-extra-options/src/one_life.c.content:
#include "modding.h"
#include "extra_options.h"
#include "recompconfig.h"

#define SAVE_READ32(off) \
    (*(volatile signed int *)((char *)D_8015C608_15D208 + (off)))
#define SAVE_WRITE32(off, value) \
    (*(volatile signed int *)((char *)D_8015C608_15D208 + (off)) = \
         (signed int)(value))

#define CURRENT_HP_OFFSET (-0x21)
#define RUNTIME_LIVES_OFFSET (-0x1C)
#define SAVE_LIVES_OFFSET 0x78

#define CURRENT_HP_READ() \
    (*(volatile unsigned char *)((char *)D_8015C608_15D208 + CURRENT_HP_OFFSET))

static int one_life_is_enabled(void)
{
    /* Enabled is the first enum entry in mod.toml, so its value is zero. */
    return recomp_get_config_u32("one_life") == 0;
}

RECOMP_HOOK_RETURN("func_80002040_2C40")
void extra_options_one_life_frame_hook(void)
{
    if (!extra_options_save_is_loaded() ||
        !one_life_is_enabled() || CURRENT_HP_READ() == 0)
    {
        return;
    }

    if (SAVE_READ32(RUNTIME_LIVES_OFFSET) != 1 ||
        SAVE_READ32(SAVE_LIVES_OFFSET) != 1)
    {
        /* The game decrements the runtime value on death and game-overs when
         * it reaches zero. Mirror the save copy so reloads retain the rule. */
        SAVE_WRITE32(RUNTIME_LIVES_OFFSET, 1);
        SAVE_WRITE32(SAVE_LIVES_OFFSET, 1);
    }
}

