mnsg-recomp-example/include/anchor_remot.content:
#ifndef ANCHOR_REMOTE_ANIMATION_H
#define ANCHOR_REMOTE_ANIMATION_H

#define ANCHOR_REMOTE_ANIMATION_MAX_CORRECTION_STEP 0.5f
#define ANCHOR_REMOTE_ANIMATION_SNAP_THRESHOLD 3.0f

/* One authoritative animation sample. Frame and endpoint_step are expressed
 * in source-clip frames; native_step is already expressed in target-clip
 * frames. The helper maps source phase/rate onto target_frame_count before it
 * advances the receiver clock. */
typedef struct AnchorRemoteAnimationInput
{
    int action;
    int seq;
    int new_sample;
    float source_frame_count;
    float target_frame_count;
    float target_frame;
    int endpoint_step_valid;
    float endpoint_step;
    float native_step;
    int root_phase_lead_frames;
} AnchorRemoteAnimationInput;

/* Pure visual clock state. endpoint_step and native_step are retained in
 * target-clip frames per 30 Hz game tick so ticks without a packet do not
 * depend on repeated input fields. */
typedef struct AnchorRemoteAnimationState
{
    int initialized;
    int action;
    int seq;
    int endpoint_step_valid;
    float frame;
    float frame_count;
    float endpoint_step;
    float native_step;
    float playback_step;
    float correction_debt;
} AnchorRemoteAnimationState;

typedef struct AnchorRemoteAnimationOutput
{
    float frame;
    float playback_step;
    float correction_step;
    float correction_debt;
    int consumed_sample;
    int snapped;
} AnchorRemoteAnimationOutput;

void anchor_remote_animation_reset(AnchorRemoteAnimationState *state);

/* Preserve an ordinary forward loop wrap while rejecting a same-action frame
 * reset whose one-tick delta cannot be a native playback rate. */
int anchor_remote_animation_step_is_continuous(int frame_restarted,
                                               int endpoint_step_valid,
                                               int endpoint_step_100);

/* Advance one 30 Hz receiver tick. A changed nonzero sequence is sufficient
 * to identify a sample; new_sample supports legacy/repeated sequence values.
 * First authority and action changes snap to the phase-projected target.
 * Same-action phase error is repaid monotonically at no more than half a clip
 * frame per tick, unless its shortest-loop distance exceeds three frames. */
void anchor_remote_animation_step(AnchorRemoteAnimationState *state,
                                  const AnchorRemoteAnimationInput *input,
                                  AnchorRemoteAnimationOutput *output);

#endif

#ifndef ANCHOR_REMOTE_MOTION_H
#define ANCHOR_REMOTE_MOTION_H

typedef struct AnchorRemoteMotionVec3
{
    float x;
    float y;
    float z;
} AnchorRemoteMotionVec3;

typedef struct AnchorRemoteMotionSample
{
    int room;
    int seq;
    /* Sender monotonic milliseconds, masked to a positive 31-bit value. */
    int timestamp_ms;
    AnchorRemoteMotionVec3 position;
    /* Post-collision world units per second at the sample endpoint. */
    AnchorRemoteMotionVec3 velocity;
    /* Signed 16-bit angle units per second at the sample endpoint. */
    AnchorRemoteMotionVec3 angular_velocity;
    int action;
    int rot_x;
    int rot_y;
    int rot_z;
} AnchorRemoteMotionSample;

typedef struct AnchorRemoteMotionOutput
{
    AnchorRemoteMotionVec3 position;
    int rot_x;
    int rot_y;
    int rot_z;
    int consumed_sample;
} AnchorRemoteMotionOutput;

/* Per-peer visual-only motion state. The receiver carries the sender's latest
 * post-collision displacement every game tick and pays packet residuals in
 * a few fixed steps. It does not delay the transform by a packet or run a
 * second gameplay/collision simulation. */
typedef struct AnchorRemoteMotionState
{
    int initialized;
    int room;
    int seq;
    int timestamp_ms;
    int frames_since_sample;
    int expected_interval_frames;
    int projection_lead_frames;
    int prediction_frames;
    int correction_frames;
    int rotation_correction_frames;

    AnchorRemoteMotionVec3 position;
    AnchorRemoteMotionVec3 velocity_per_frame;
    AnchorRemoteMotionVec3 correction_per_frame;
    AnchorRemoteMotionVec3 correction_debt;
    float vertical_acceleration_per_frame;
    int use_native_gravity_limit;
    AnchorRemoteMotionVec3 rotation;
    AnchorRemoteMotionVec3 angular_velocity_per_frame;
    AnchorRemoteMotionVec3 rotation_correction_per_frame;

    AnchorRemoteMotionVec3 raw_position;
    AnchorRemoteMotionVec3 raw_velocity_per_frame;
    AnchorRemoteMotionVec3 raw_rotation;
    AnchorRemoteMotionVec3 raw_angular_velocity_per_frame;
    int raw_action;
} AnchorRemoteMotionState;

void anchor_remote_motion_reset(AnchorRemoteMotionState *state);

/* Shared sender/receiver helpers. A sparse edge is a start, stop, or strong
 * sign reversal around a 25-percent hysteresis band derived from the supplied
 * quantization threshold. */
int anchor_remote_motion_axis_has_edge(int previous_velocity,
                                       int current_velocity,
                                       int minimum_velocity);
int anchor_remote_motion_angle_delta_s16(int target, int current);

/* Advance one 30 Hz game tick and consume a new authoritative sample when
 * its sequence or legacy payload changes. Returns nonzero when the transform
 * was deliberately snapped because prediction would be invalid. */
int anchor_remote_motion_step(AnchorRemoteMotionState *state,
                              const AnchorRemoteMotionSample *sample,
                              AnchorRemoteMotionOutput *output);

#endif

