/**
 * @file anchor_connect_ui.c
 * @brief Anchor Multiplayer connection setup screen.
 *
 * Provides two persistent UI contexts:
 *
 *  1. **Connection modal** – opened when the player clicks the NET button.
 *     Players fill in server address, port, room ID, player name and team,
 *     then click "Connect" or "Skip / Play Offline" to dismiss it.
 *
 *  2. **"NET" toggle button** – a small button fixed to the bottom-left
 *     corner that reopens the connection modal at any time during gameplay,
 *     allowing players to disconnect or change settings.
 *
 * The connection modal is created lazily on the very first game frame via a
 * RECOMP_HOOK_RETURN on func_80002040_2C40 (the same hook used by debug.c
 * and anchor_ui.c).  The callback/frame-hook pattern from debug.c is used
 * throughout: callbacks only set flags, never call context API functions
 * directly; the frame hook drains those flags on the next frame.
 */

#include "modding.h"
#include "recomputils.h"
#include "recompui.h"
#include "recompconfig.h"
#include "anchor.h"
#include "utils/room_utils.h"
#include "utils/string_utils.h"

/* =========================================================================
   Colour palette
   ========================================================================= */

static const RecompuiColor CC_BG = {10, 10, 15, 242};
static const RecompuiColor CC_BORDER = {60, 60, 80, 210};
static const RecompuiColor CC_TITLE_BG = {14, 14, 22, 255};
static const RecompuiColor CC_OVERLAY = {0, 0, 0, 160};
static const RecompuiColor CC_WHITE = {255, 255, 255, 255};
static const RecompuiColor CC_DIM = {165, 165, 175, 255};
static const RecompuiColor CC_TEAL = {0, 178, 158, 255};
static const RecompuiColor CC_GREEN = {55, 175, 75, 255};
static const RecompuiColor CC_RED = {210, 60, 60, 255};
static const RecompuiColor CC_STATUS = {12, 12, 20, 255};
static const RecompuiColor CC_TOGGLE = {10, 10, 18, 210};
static const RecompuiColor CC_FIELDS_LOCK = {10, 10, 15, 155}; /* overlay when connected */

/* =========================================================================
   UI state
   ========================================================================= */

/* Small always-visible "NET" toggle button. */
/* Button is hosted inside debug.c's toggle context to share Z-order. */

/* Full-screen connection-setup modal. */
static RecompuiContext s_modal_ctx = RECOMPUI_NULL_CONTEXT;

static int s_initialized = 0;   /* one-time lazy init guard */
static int s_modal_visible = 0; /* current show/hide state of the modal */

/* Text-input field handles (read when Connect is pressed). */
static RecompuiResource s_in_host = RECOMPUI_NULL_RESOURCE;
static RecompuiResource s_in_port = RECOMPUI_NULL_RESOURCE;
static RecompuiResource s_in_room = RECOMPUI_NULL_RESOURCE;
static RecompuiResource s_in_name = RECOMPUI_NULL_RESOURCE;
static RecompuiResource s_in_team = RECOMPUI_NULL_RESOURCE;

/* Dynamic label / button handles updated at runtime. */
static RecompuiResource s_status_lbl = RECOMPUI_NULL_RESOURCE;
static RecompuiResource s_disconnect_btn = RECOMPUI_NULL_RESOURCE;
static RecompuiResource s_connect_btn = RECOMPUI_NULL_RESOURCE;
static RecompuiResource s_skip_btn = RECOMPUI_NULL_RESOURCE;
/* Semi-transparent overlay that covers the input fields when connected,
 * preventing the user from editing them.                                */
static RecompuiResource s_fields_overlay = RECOMPUI_NULL_RESOURCE;

/* Deferred actions set inside callbacks, consumed by the frame hook.
 * Context API calls are forbidden inside callbacks; they are made here. */
static int s_pending_open = 0;
static int s_pending_close = 0;
static int s_pending_connect = 0;
static int s_pending_disconnect = 0;

/* Pending status text and its colour indication (1=green / 0=red). */
static const char *s_pending_status = 0;
static int s_pending_status_ok = 0;

/* =========================================================================
   Callbacks  (flag-setters only – no context API calls inside)
   ========================================================================= */

/* Public: called by debug.c's toggle-context NET button callback. */
void anchor_connect_ui_net_btn_callback(RecompuiResource res,
                                        const RecompuiEventData *ev, void *ud)
{
    (void)res;
    (void)ud;
    if (ev->type != UI_EVENT_CLICK)
        return;
    if (s_modal_visible)
        s_pending_close = 1;
    else
        s_pending_open = 1;
}

static void on_close_clicked(RecompuiResource res,
                             const RecompuiEventData *ev, void *ud)
{
    (void)res;
    (void)ud;
    if (ev->type != UI_EVENT_CLICK)
        return;
    s_pending_close = 1;
}

static void on_connect_clicked(RecompuiResource res,
                               const RecompuiEventData *ev, void *ud)
{
    (void)res;
    (void)ud;
    if (ev->type != UI_EVENT_CLICK)
        return;
    s_pending_connect = 1;
}

static void on_skip_clicked(RecompuiResource res,
                            const RecompuiEventData *ev, void *ud)
{
    (void)res;
    (void)ud;
    if (ev->type != UI_EVENT_CLICK)
        return;
    s_pending_close = 1;
}

static void on_disconnect_clicked(RecompuiResource res,
                                  const RecompuiEventData *ev, void *ud)
{
    (void)res;
    (void)ud;
    if (ev->type != UI_EVENT_CLICK)
        return;
    s_pending_disconnect = 1;
}

/* =========================================================================
   UI construction  (called once from the frame hook)
   ========================================================================= */

/** Build a labeled text-input row inside @p parent and store the input in *@p out. */
static void make_field(RecompuiContext ctx, RecompuiResource parent,
                       const char *label_text, const char *default_text,
                       RecompuiResource *out)
{
    RecompuiResource lbl = recompui_create_label(ctx, parent, label_text, LABELSTYLE_SMALL);
    recompui_set_color(lbl, &CC_DIM);
    recompui_set_font_size(lbl, 16.0f, UNIT_DP);
    recompui_set_margin_bottom(lbl, -4.0f, UNIT_DP);

    *out = recompui_create_textinput(ctx, parent);
    recompui_set_font_size(*out, 18.0f, UNIT_DP);
    recompui_set_max_width(*out, 100.0f, UNIT_PERCENT);
    recompui_set_input_text(*out, default_text);
}

static void make_field_hint(RecompuiContext ctx, RecompuiResource parent,
                            const char *text)
{
    RecompuiResource hint = recompui_create_label(
        ctx, parent, text, LABELSTYLE_SMALL);
    recompui_set_color(hint, &CC_DIM);
    recompui_set_font_size(hint, 13.0f, UNIT_DP);
    recompui_set_max_width(hint, 100.0f, UNIT_PERCENT);
}

static void connect_ui_init(void)
{
    /* ── Read mod-config defaults for input pre-population ─────────── */
    char *cfg_host = recomp_get_config_string("anchor_host");
    char *cfg_room = recomp_get_config_string("anchor_room_id_new");
    char *cfg_name = recomp_get_config_string("anchor_player_name");
    char *cfg_team = recomp_get_config_string("anchor_team_id");

    int cfg_port = (int)recomp_get_config_double("anchor_port");
    if (cfg_port <= 0)
        cfg_port = 43383;

    static char port_str[8];
    mnsg_string_write_s32(port_str, cfg_port);

    /* ── Connection-setup modal ─────────────────────────────────────── */
    s_modal_ctx = recompui_create_context();
    recompui_set_context_captures_input(s_modal_ctx, 1);
    recompui_set_context_captures_mouse(s_modal_ctx, 1);

    recompui_open_context(s_modal_ctx);
    {
        /* Follow the same two-sibling pattern used throughout this codebase
         * (see debug.c): the root has no styling; an absolutely-positioned
         * overlay element dims the scene; a second absolutely-positioned
         * panel element holds all the interactive content.  Using the root
         * itself as the overlay (flex container) causes the recompui layer
         * to swallow mouse events before they reach the children.           */
        RecompuiResource root = recompui_context_root(s_modal_ctx);

        /* ── Full-screen dim overlay (sibling of the panel) ─────────── */
        RecompuiResource overlay = recompui_create_element(s_modal_ctx, root);
        recompui_set_position(overlay, POSITION_ABSOLUTE);
        recompui_set_left(overlay, 0.0f, UNIT_PERCENT);
        recompui_set_top(overlay, 0.0f, UNIT_PERCENT);
        recompui_set_width(overlay, 100.0f, UNIT_PERCENT);
        recompui_set_height(overlay, 100.0f, UNIT_PERCENT);
        recompui_set_background_color(overlay, &CC_OVERLAY);

        /* ── Panel: absolute-centred, 520 dp wide ────────────────────── */
        RecompuiResource panel = recompui_create_element(s_modal_ctx, root);
        recompui_set_position(panel, POSITION_ABSOLUTE);
        recompui_set_left(panel, 50.0f, UNIT_PERCENT);
        recompui_set_top(panel, 15.0f, UNIT_PERCENT);
        recompui_set_margin_left(panel, -260.0f, UNIT_DP); /* centre horizontally */
        recompui_set_width(panel, 520.0f, UNIT_DP);
        recompui_set_height_auto(panel);
        recompui_set_background_color(panel, &CC_BG);
        recompui_set_border_radius(panel, 10.0f, UNIT_DP);
        recompui_set_border_width(panel, 1.5f, UNIT_DP);
        recompui_set_border_color(panel, &CC_BORDER);
        recompui_set_display(panel, DISPLAY_FLEX);
        recompui_set_flex_direction(panel, FLEX_DIRECTION_COLUMN);

        /* ── Teal accent stripe at the top ──────────────────────────── */
        RecompuiResource accent = recompui_create_element(s_modal_ctx, panel);
        recompui_set_width(accent, 100.0f, UNIT_PERCENT);
        recompui_set_height(accent, 5.0f, UNIT_DP);
        recompui_set_border_top_left_radius(accent, 10.0f, UNIT_DP);
        recompui_set_border_top_right_radius(accent, 10.0f, UNIT_DP);
        recompui_set_background_color(accent, &CC_TEAL);

        /* ── Header: title + close button ───────────────────────────── */
        RecompuiResource hdr = recompui_create_element(s_modal_ctx, panel);
        recompui_set_display(hdr, DISPLAY_FLEX);
        recompui_set_flex_direction(hdr, FLEX_DIRECTION_ROW);
        recompui_set_align_items(hdr, ALIGN_ITEMS_CENTER);
        recompui_set_justify_content(hdr, JUSTIFY_CONTENT_SPACE_BETWEEN);
        recompui_set_padding_left(hdr, 20.0f, UNIT_DP);
        recompui_set_padding_right(hdr, 14.0f, UNIT_DP);
        recompui_set_padding_top(hdr, 16.0f, UNIT_DP);
        recompui_set_padding_bottom(hdr, 16.0f, UNIT_DP);
        recompui_set_background_color(hdr, &CC_TITLE_BG);
        recompui_set_border_bottom_width(hdr, 1.0f, UNIT_DP);
        recompui_set_border_bottom_color(hdr, &CC_BORDER);

        RecompuiResource title = recompui_create_label(
            s_modal_ctx, hdr, "Anchor Multiplayer Setup", LABELSTYLE_NORMAL);
        recompui_set_color(title, &CC_TEAL);
        recompui_set_font_weight(title, 700);
        recompui_set_font_size(title, 22.0f, UNIT_DP);

        RecompuiResource close_btn = recompui_create_button(
            s_modal_ctx, hdr, "X", BUTTONSTYLE_SECONDARY);
        recompui_set_cursor(close_btn, CURSOR_POINTER);
        recompui_set_font_size(close_btn, 18.0f, UNIT_DP);
        recompui_set_tab_index(close_btn, TAB_INDEX_AUTO);
        recompui_register_callback(close_btn, on_close_clicked, 0);

        /* ── Body: use outer padding + column flex ───────────────────── */
        RecompuiResource body = recompui_create_element(s_modal_ctx, panel);
        recompui_set_display(body, DISPLAY_FLEX);
        recompui_set_flex_direction(body, FLEX_DIRECTION_COLUMN);
        recompui_set_padding(body, 20.0f, UNIT_DP);
        recompui_set_gap(body, 12.0f, UNIT_DP);

        /* ── Description text ───────────────────────────────────────── */
        RecompuiResource desc = recompui_create_label(
            s_modal_ctx, body,
            "Connect to an Anchor server to sync items & flags with teammates.\n"
            "Enter a private Room ID, then review the remaining settings.",
            LABELSTYLE_SMALL);
        recompui_set_color(desc, &CC_DIM);
        recompui_set_font_size(desc, 15.0f, UNIT_DP);

        /* ── Fields wrapper: relative-positioned so the lock overlay works ── */
        RecompuiResource fields_wrap = recompui_create_element(s_modal_ctx, body);
        recompui_set_display(fields_wrap, DISPLAY_FLEX);
        recompui_set_flex_direction(fields_wrap, FLEX_DIRECTION_COLUMN);
        recompui_set_gap(fields_wrap, 12.0f, UNIT_DP);
        recompui_set_position(fields_wrap, POSITION_RELATIVE);

        /* ── Two-column row for Address (left) and Port (right) ──────── */
        RecompuiResource addr_row = recompui_create_element(s_modal_ctx, fields_wrap);
        recompui_set_display(addr_row, DISPLAY_FLEX);
        recompui_set_flex_direction(addr_row, FLEX_DIRECTION_ROW);
        recompui_set_gap(addr_row, 12.0f, UNIT_DP);
        recompui_set_align_items(addr_row, ALIGN_ITEMS_FLEX_END);

        /* Address column (grows to fill available space). */
        RecompuiResource addr_col = recompui_create_element(s_modal_ctx, addr_row);
        recompui_set_display(addr_col, DISPLAY_FLEX);
        recompui_set_flex_direction(addr_col, FLEX_DIRECTION_COLUMN);
        recompui_set_flex_grow(addr_col, 1.0f);
        recompui_set_gap(addr_col, 4.0f, UNIT_DP);
        make_field(s_modal_ctx, addr_col, "Server Address",
                   (cfg_host && cfg_host[0]) ? cfg_host : "anchor.hm64.org",
                   &s_in_host);

        /* Port column (fixed 100 dp). */
        RecompuiResource port_col = recompui_create_element(s_modal_ctx, addr_row);
        recompui_set_display(port_col, DISPLAY_FLEX);
        recompui_set_flex_direction(port_col, FLEX_DIRECTION_COLUMN);
        recompui_set_width(port_col, 100.0f, UNIT_DP);
        recompui_set_gap(port_col, 4.0f, UNIT_DP);
        make_field(s_modal_ctx, port_col, "Port", port_str, &s_in_port);

        /* ── Remaining full-width fields ────────────────────────────── */
        RecompuiResource room_col = recompui_create_element(s_modal_ctx, fields_wrap);
        recompui_set_display(room_col, DISPLAY_FLEX);
        recompui_set_flex_direction(room_col, FLEX_DIRECTION_COLUMN);
        recompui_set_gap(room_col, 4.0f, UNIT_DP);
        make_field(s_modal_ctx, room_col, "Room ID",
                   cfg_room ? cfg_room : "",
                   &s_in_room);
        make_field_hint(
            s_modal_ctx, room_col,
            "A private code for this session. Use a unique Room ID and share "
            "it only with people you want to join.");

        /* Two-column row: Player Name (left) + Team Name (right). */
        RecompuiResource nt_row = recompui_create_element(s_modal_ctx, fields_wrap);
        recompui_set_display(nt_row, DISPLAY_FLEX);
        recompui_set_flex_direction(nt_row, FLEX_DIRECTION_ROW);
        recompui_set_gap(nt_row, 12.0f, UNIT_DP);
        recompui_set_align_items(nt_row, ALIGN_ITEMS_FLEX_START);

        RecompuiResource name_col = recompui_create_element(s_modal_ctx, nt_row);
        recompui_set_display(name_col, DISPLAY_FLEX);
        recompui_set_flex_direction(name_col, FLEX_DIRECTION_COLUMN);
        recompui_set_flex_grow(name_col, 1.0f);
        recompui_set_gap(name_col, 4.0f, UNIT_DP);
        make_field(s_modal_ctx, name_col, "Player Name",
                   (cfg_name && cfg_name[0]) ? cfg_name : "Player",
                   &s_in_name);

        RecompuiResource team_col = recompui_create_element(s_modal_ctx, nt_row);
        recompui_set_display(team_col, DISPLAY_FLEX);
        recompui_set_flex_direction(team_col, FLEX_DIRECTION_COLUMN);
        recompui_set_flex_grow(team_col, 1.0f);
        recompui_set_gap(team_col, 4.0f, UNIT_DP);
        make_field(s_modal_ctx, team_col, "Team Name",
                   (cfg_team && cfg_team[0]) ? cfg_team : "default",
                   &s_in_team);
        make_field_hint(
            s_modal_ctx, team_col,
            "Players with the same Team Name share and sync game progression.");

        /* ── Lock overlay: covers all fields when connected ─────────── */
        s_fields_overlay = recompui_create_element(s_modal_ctx, fields_wrap);
        recompui_set_position(s_fields_overlay, POSITION_ABSOLUTE);
        recompui_set_left(s_fields_overlay, 0.0f, UNIT_PERCENT);
        recompui_set_top(s_fields_overlay, 0.0f, UNIT_PERCENT);
        recompui_set_width(s_fields_overlay, 100.0f, UNIT_PERCENT);
        recompui_set_height(s_fields_overlay, 100.0f, UNIT_PERCENT);
        recompui_set_background_color(s_fields_overlay, &CC_FIELDS_LOCK);
        recompui_set_display(s_fields_overlay, DISPLAY_NONE);

        /* ── Status bar ─────────────────────────────────────────────── */
        RecompuiResource status_row = recompui_create_element(s_modal_ctx, body);
        recompui_set_display(status_row, DISPLAY_FLEX);
        recompui_set_align_items(status_row, ALIGN_ITEMS_CENTER);
        recompui_set_padding_left(status_row, 12.0f, UNIT_DP);
        recompui_set_padding_right(status_row, 12.0f, UNIT_DP);
        recompui_set_padding_top(status_row, 10.0f, UNIT_DP);
        recompui_set_padding_bottom(status_row, 10.0f, UNIT_DP);
        recompui_set_background_color(status_row, &CC_STATUS);
        recompui_set_border_radius(status_row, 5.0f, UNIT_DP);
        recompui_set_min_height(status_row, 44.0f, UNIT_DP);

        s_status_lbl = recompui_create_label(
            s_modal_ctx, status_row,
            "Enter a Room ID and click Connect, or click Skip to play offline.",
            LABELSTYLE_SMALL);
        recompui_set_color(s_status_lbl, &CC_DIM);
        recompui_set_font_size(s_status_lbl, 15.0f, UNIT_DP);

        /* ── Button row ─────────────────────────────────────────────── */
        RecompuiResource btn_row = recompui_create_element(s_modal_ctx, body);
        recompui_set_display(btn_row, DISPLAY_FLEX);
        recompui_set_flex_direction(btn_row, FLEX_DIRECTION_ROW);
        recompui_set_gap(btn_row, 10.0f, UNIT_DP);
        recompui_set_justify_content(btn_row, JUSTIFY_CONTENT_FLEX_END);

        /* Skip button (secondary, rightmost but before Connect). */
        s_skip_btn = recompui_create_button(
            s_modal_ctx, btn_row, "Skip / Play Offline", BUTTONSTYLE_SECONDARY);
        recompui_set_cursor(s_skip_btn, CURSOR_POINTER);
        recompui_set_font_size(s_skip_btn, 16.0f, UNIT_DP);
        recompui_set_tab_index(s_skip_btn, TAB_INDEX_AUTO);
        recompui_register_callback(s_skip_btn, on_skip_clicked, 0);

        /* Disconnect button (hidden until connected). */
        s_disconnect_btn = recompui_create_button(
            s_modal_ctx, btn_row, "Disconnect", BUTTONSTYLE_SECONDARY);
        recompui_set_cursor(s_disconnect_btn, CURSOR_POINTER);
        recompui_set_font_size(s_disconnect_btn, 16.0f, UNIT_DP);
        recompui_set_tab_index(s_disconnect_btn, TAB_INDEX_AUTO);
        recompui_set_display(s_disconnect_btn, DISPLAY_NONE);
        recompui_register_callback(s_disconnect_btn, on_disconnect_clicked, 0);

        /* Connect button (primary, rightmost). Hidden when connected. */
        s_connect_btn = recompui_create_button(
            s_modal_ctx, btn_row, "Connect", BUTTONSTYLE_PRIMARY);
        recompui_set_cursor(s_connect_btn, CURSOR_POINTER);
        recompui_set_font_size(s_connect_btn, 16.0f, UNIT_DP);
        recompui_set_tab_index(s_connect_btn, TAB_INDEX_AUTO);
        recompui_register_callback(s_connect_btn, on_connect_clicked, 0);
    }
    recompui_close_context(s_modal_ctx);

    /* Free config strings (must use recomp_free_config_string). */
    if (cfg_host)
        recomp_free_config_string(cfg_host);
    if (cfg_room)
        recomp_free_config_string(cfg_room);
    if (cfg_name)
        recomp_free_config_string(cfg_name);
    if (cfg_team)
        recomp_free_config_string(cfg_team);
}

/* =========================================================================
   Internal: update modal's dynamic state (status label + disconnect button)
   Must only be called from the frame hook (not inside a callback).
   ========================================================================= */

static void apply_status_update(void)
{
    if (!s_pending_status || !s_modal_visible)
    {
        s_pending_status = 0;
        return;
    }

    recompui_open_context(s_modal_ctx);

    /* Update status text and colour. */
    recompui_set_text(s_status_lbl, s_pending_status);
    recompui_set_color(s_status_lbl,
                       s_pending_status_ok ? &CC_GREEN : &CC_RED);

    /* Sync button visibility with current connection state. */
    int connected = anchor_is_connected();
    recompui_set_display(s_connect_btn, connected ? DISPLAY_NONE : DISPLAY_BLOCK);
    recompui_set_display(s_skip_btn, connected ? DISPLAY_NONE : DISPLAY_BLOCK);
    recompui_set_display(s_disconnect_btn, connected ? DISPLAY_BLOCK : DISPLAY_NONE);
    recompui_set_display(s_fields_overlay, connected ? DISPLAY_BLOCK : DISPLAY_NONE);

    recompui_close_context(s_modal_ctx);
    s_pending_status = 0;
}

/* =========================================================================
   Per-frame hook
   ========================================================================= */

/**
 * Hooked on the game's main per-frame tick.  On the very first frame it
 * builds all UI; thereafter it drains the pending-action flags produced by
 * the NET button and modal callbacks. Startup flow is handled by
 * startup_menu.c and startup_multiplayer_ui.c.
 */
RECOMP_HOOK_RETURN("func_80002040_2C40")
void anchor_connect_ui_frame_hook(void)
{
    /* ── One-time lazy initialisation (frame 1 only) ────────────────── */
    if (!s_initialized)
    {
        s_initialized = 1;
        connect_ui_init();
        return;
    }

    /* ── Connect action ─────────────────────────────────────────────── */
    if (s_pending_connect)
    {
        s_pending_connect = 0;

        /* Read all input fields in one open/close block. */
        recompui_open_context(s_modal_ctx);
        char *host_str = recompui_get_input_text(s_in_host);
        char *port_str = recompui_get_input_text(s_in_port);
        char *room_str = recompui_get_input_text(s_in_room);
        char *name_str = recompui_get_input_text(s_in_name);
        char *team_str = recompui_get_input_text(s_in_team);
        recompui_close_context(s_modal_ctx);

        int port = mnsg_string_to_s32(port_str, 43383);
        if (port <= 0 || port > 65535)
            port = 43383;

        /* Never collapse an empty field into a shared fallback room.  Check
         * before disconnecting so a typo cannot drop a live session. */
        if (!mnsg_room_id_is_valid(room_str))
        {
            s_pending_status = "Enter a Room ID before connecting.";
            s_pending_status_ok = 0;
            goto connect_cleanup;
        }

        /* Disconnect first if already connected. */
        if (anchor_is_connected())
            anchor_disconnect();

        int ok = anchor_connect(
            (host_str && host_str[0]) ? host_str : "anchor.hm64.org",
            port,
            room_str,
            (name_str && name_str[0]) ? name_str : "Player",
            0, /* client_id = 0 → let the server assign one */
            (team_str && team_str[0]) ? team_str : "default");

        // int ok = 1;
        if (ok)
        {
            /* Close the modal next frame exactly like Skip/X does. */
            s_pending_close = 1;
        }
        else
        {
            s_pending_status = "Connection failed \xe2\x80\x93 check address / port and try again.";
            s_pending_status_ok = 0;
        }

    connect_cleanup:
        if (host_str)
            recomp_free(host_str);
        if (port_str)
            recomp_free(port_str);
        if (room_str)
            recomp_free(room_str);
        if (name_str)
            recomp_free(name_str);
        if (team_str)
            recomp_free(team_str);
    }

    /* ── Disconnect action ──────────────────────────────────────────── */
    if (s_pending_disconnect)
    {
        s_pending_disconnect = 0;
        anchor_disconnect();
        s_pending_status =
            "Disconnected. Update settings and reconnect, or close to play offline.";
        s_pending_status_ok = 0;
        /* Restore the Connect button / remove the field lock immediately
         * since the modal stays visible after disconnecting.             */
        recompui_open_context(s_modal_ctx);
        recompui_set_display(s_connect_btn, DISPLAY_BLOCK);
        recompui_set_display(s_skip_btn, DISPLAY_BLOCK);
        recompui_set_display(s_disconnect_btn, DISPLAY_NONE);
        recompui_set_display(s_fields_overlay, DISPLAY_NONE);
        recompui_close_context(s_modal_ctx);
    }

    /* ── Open modal ─────────────────────────────────────────────────── */
    if (s_pending_open)
    {
        s_pending_open = 0;
        if (!s_modal_visible)
        {
            /* Refresh UI state to match current connection state. */
            int connected = anchor_is_connected();
            recompui_open_context(s_modal_ctx);
            /* Connect button only shown when not connected; Disconnect
             * button only shown when connected.                          */
            recompui_set_display(s_connect_btn,
                                 connected ? DISPLAY_NONE : DISPLAY_BLOCK);
            recompui_set_display(s_skip_btn,
                                 connected ? DISPLAY_NONE : DISPLAY_BLOCK);
            recompui_set_display(s_disconnect_btn,
                                 connected ? DISPLAY_BLOCK : DISPLAY_NONE);
            /* Lock overlay blocks editing of fields while connected.    */
            recompui_set_display(s_fields_overlay,
                                 connected ? DISPLAY_BLOCK : DISPLAY_NONE);
            if (connected)
            {
                recompui_set_text(s_status_lbl,
                                  "Currently connected. Disconnect to change settings.");
                recompui_set_color(s_status_lbl, &CC_GREEN);
            }
            else
            {
                recompui_set_text(s_status_lbl,
                                  "Not connected. Enter a Room ID and click "
                                  "Connect, or close to stay offline.");
                recompui_set_color(s_status_lbl, &CC_DIM);
            }
            recompui_close_context(s_modal_ctx);

            recompui_show_context(s_modal_ctx);
            s_modal_visible = 1;
        }
    }

    /* ── Close modal ────────────────────────────────────────────────── */
    if (s_pending_close)
    {
        s_pending_close = 0;
        if (s_modal_visible)
        {
            recompui_hide_context(s_modal_ctx);
            // recompui_close_context(s_modal_ctx);

            s_modal_visible = 0;
        }
    }

    /* ── Flush status-label update from connect/disconnect ──────────── */
    apply_status_update();
}

mnsg-recomp-example/src/ui/anchor_ui.c.content:
/**
 * @file anchor_ui.c
 * @brief Anchor UI overlays for MNSG: Recompiled.
 *
 * Provides two persistent overlay contexts:
 *
 *  1. **Connection notification banner** – a brief popup that appears near
 *     the top of the screen every time a connection attempt is made.  The
 *     accent bar is green on success, red on failure.  It auto-dismisses
 *     after NOTIFICATION_FRAMES game frames (~5 s at 60 fps).
 *
 *  2. **Player list panel** – a semi-transparent panel anchored to the
 *     top-left corner that lists the names of every player currently in the
 *     Anchor room.  It is refreshed once per second while connected, and
 *     hidden automatically when the client disconnects.
 *
 * Both contexts are created lazily on first use and never capture keyboard
 * or mouse input so they never interfere with gameplay.
 *
 * Entry points
 * ------------
 *   anchor_ui_update()        – RECOMP_HOOK_RETURN on func_80002040_2C40
 *       drives the timer and the player-list refresh.
 */

#include "modding.h"
#include "recomputils.h"
#include "recompui.h"
#include "recompconfig.h"
#include "anchor.h"
#include "anchor_runtime.h"
#include "icon_goemon.h"
#include "icon_ebisumaru.h"
#include "icon_sasuke.h"
#include "icon_yae.h"

/* Provided by debug.c – re-raises the toggle-button context to the top of
 * the recompui Z-stack after any other persistent context is shown.         */
extern void debug_ui_bump_toggle_ctx(void);

/* =========================================================================
   Tunables
   ========================================================================= */

/** Frames the connection notification stays on screen (~5 s @ 60 fps). */
#define NOTIFICATION_FRAMES 300

/** Frames between player-list refreshes (~1 s @ 60 fps). */
#define PLAYER_LIST_REFRESH_FRAMES 60

/** Maximum player rows shown in the list panel. */
#define MAX_DISPLAY_PLAYERS 16

/** Icon image size in DP units (square). */
#define ICON_SIZE 24.0f

/** Width of the player-list panel in DP units. */
#define PANEL_WIDTH 300.0f

/** Maximum characters in a composed player-list label. */
#define PLAYER_LABEL_BUF_LEN 192

/* =========================================================================
   Colour constants
   ========================================================================= */

static const RecompuiColor COLOR_BG = {0, 0, 0, 180};
static const RecompuiColor COLOR_BORDER = {80, 80, 80, 200};
static const RecompuiColor COLOR_WHITE = {255, 255, 255, 255};
static const RecompuiColor COLOR_DIM = {180, 180, 180, 255};
static const RecompuiColor COLOR_GREEN = {80, 200, 80, 255};
static const RecompuiColor COLOR_RED = {220, 60, 60, 255};
static const RecompuiColor COLOR_GOLD = {220, 190, 60, 255};
static const RecompuiColor COLOR_ACCENT_BG = {20, 20, 20, 200};
static const RecompuiColor COLOR_TEAM_HDR = {0, 160, 140, 255}; /* muted teal for team section labels */

/* =========================================================================
   Notification context
   ========================================================================= */

static RecompuiContext s_notif_ctx = RECOMPUI_NULL_CONTEXT;
static RecompuiResource s_notif_accent = RECOMPUI_NULL_RESOURCE;
static RecompuiResource s_notif_msg = RECOMPUI_NULL_RESOURCE;
static int s_notif_timer = 0;

static void notif_ensure_init(void)
{
    if (s_notif_ctx != RECOMPUI_NULL_CONTEXT)
        return;

    s_notif_ctx = recompui_create_context();
    recompui_set_context_captures_input(s_notif_ctx, 0);
    recompui_set_context_captures_mouse(s_notif_ctx, 0);
    recompui_open_context(s_notif_ctx);

    RecompuiResource root = recompui_context_root(s_notif_ctx);

    /* Outer card: centered horizontally, near the top. */
    RecompuiResource card = recompui_create_element(s_notif_ctx, root);
    recompui_set_position(card, POSITION_ABSOLUTE);
    recompui_set_left(card, 50.0f, UNIT_PERCENT);
    recompui_set_top(card, 56.0f, UNIT_DP);
    recompui_set_margin_left(card, -160.0f, UNIT_DP); /* center: half of 320 */
    recompui_set_width(card, 320.0f, UNIT_DP);
    recompui_set_background_color(card, &COLOR_BG);
    recompui_set_border_radius(card, 8.0f, UNIT_DP);
    recompui_set_border_width(card, 1.5f, UNIT_DP);
    recompui_set_border_color(card, &COLOR_BORDER);

    /* Coloured accent stripe along the top edge. */
    s_notif_accent = recompui_create_element(s_notif_ctx, card);
    recompui_set_width(s_notif_accent, 100.0f, UNIT_PERCENT);
    recompui_set_height(s_notif_accent, 5.0f, UNIT_DP);
    recompui_set_border_top_left_radius(s_notif_accent, 8.0f, UNIT_DP);
    recompui_set_border_top_right_radius(s_notif_accent, 8.0f, UNIT_DP);
    recompui_set_background_color(s_notif_accent, &COLOR_GREEN);

    /* Notification message text. */
    s_notif_msg = recompui_create_label(s_notif_ctx, card, "Connected.", LABELSTYLE_NORMAL);
    recompui_set_padding(s_notif_msg, 10.0f, UNIT_DP);
    recompui_set_color(s_notif_msg, &COLOR_WHITE);
    recompui_set_font_size(s_notif_msg, 18.0f, UNIT_DP);

    recompui_close_context(s_notif_ctx);
}

/* =========================================================================
   Player list context
   ========================================================================= */

static RecompuiContext s_plist_ctx = RECOMPUI_NULL_CONTEXT;
static int s_plist_refresh_timer = 0;
static int s_plist_visible = 0;

/* ---- Per-player icon row resources ------------------------------------ */

typedef struct
{
    RecompuiResource row;        /* outer column container (FLEX_COLUMN)              */
    RecompuiResource team_hdr;   /* team section divider, DISPLAY_NONE by default     */
    RecompuiResource team_label; /* team name label inside team_hdr                  */
    RecompuiResource player_row; /* inner flex-row: icon + label                     */
    RecompuiResource icon;
    RecompuiResource label;
} PlayerRowUI;

static PlayerRowUI s_plist_rows[MAX_DISPLAY_PLAYERS];
static RecompuiResource s_plist_rows_container = RECOMPUI_NULL_RESOURCE;

/* Pre-loaded character textures: 0=Goemon, 1=Ebisumaru, 2=Sasuke, 3=Yae. */
static RecompuiTextureHandle s_char_textures[4];
static RecompuiTextureHandle s_blank_texture;
static int s_textures_initialized = 0;

/** Load character icon textures from baked-in C arrays. */
static void plist_load_textures(void)
{
    if (s_textures_initialized)
        return;
    s_textures_initialized = 1;

    /* 1×1 fully transparent placeholder texture. */
    static const unsigned char blank_px[4] = {0, 0, 0, 0};
    s_blank_texture = recompui_create_texture_rgba32((void *)blank_px, 1, 1);

    s_char_textures[0] = recompui_create_texture_rgba32(
        (void *)icon_goemon_data, ICON_GOEMON_WIDTH, ICON_GOEMON_HEIGHT);
    s_char_textures[1] = recompui_create_texture_rgba32(
        (void *)icon_ebisumaru_data, ICON_EBISUMARU_WIDTH, ICON_EBISUMARU_HEIGHT);
    s_char_textures[2] = recompui_create_texture_rgba32(
        (void *)icon_sasuke_data, ICON_SASUKE_WIDTH, ICON_SASUKE_HEIGHT);
    s_char_textures[3] = recompui_create_texture_rgba32(
        (void *)icon_yae_data, ICON_YAE_WIDTH, ICON_YAE_HEIGHT);
}

static void append_char_limited(char *dst, int *pos, int max_len, char value)
{
    if (*pos < max_len - 1)
        dst[(*pos)++] = value;
}

static void append_text_limited(char *dst, int *pos, int max_len, const char *text)
{
    while (*text && *pos < max_len - 1)
        dst[(*pos)++] = *text++;
}

static void append_int_limited(char *dst, int *pos, int max_len, int value)
{
    char tmp[12];
    int len = 0;
    unsigned int v;

    if (value < 0)
    {
        append_char_limited(dst, pos, max_len, '-');
        v = (unsigned int)(-(value + 1)) + 1u;
    }
    else
    {
        v = (unsigned int)value;
    }

    if (v == 0)
    {
        append_char_limited(dst, pos, max_len, '0');
        return;
    }

    while (v > 0 && len < (int)sizeof(tmp))
    {
        tmp[len++] = (char)('0' + (v % 10u));
        v /= 10u;
    }

    while (len > 0)
        append_char_limited(dst, pos, max_len, tmp[--len]);
}

static int parse_json_int_field(const char *p, char key0, char key1, int key_len, int default_value)
{
    while (*p && *p != '}')
    {
        int matched = 0;
        if (key_len == 1)
        {
            matched = (*p == '"' && *(p + 1) == key0 && *(p + 2) == '"' && *(p + 3) == ':');
        }
        else
        {
            matched = (*p == '"' && *(p + 1) == key0 && *(p + 2) == key1 &&
                       *(p + 3) == '"' && *(p + 4) == ':');
        }

        if (matched)
        {
            int sign = 1;
            int value = 0;
            p += key_len + 3; /* skip "key": */
            if (*p == '-')
            {
                sign = -1;
                p++;
            }
            while (*p >= '0' && *p <= '9')
                value = value * 10 + (*p++ - '0');
            return value * sign;
        }
        p++;
    }

    return default_value;
}

static void plist_ensure_init(void)
{
    if (s_plist_ctx != RECOMPUI_NULL_CONTEXT)
        return;

    /* Load icon textures (GPU resources, not bound to any context). */
    plist_load_textures();

    s_plist_ctx = recompui_create_context();
    recompui_set_context_captures_input(s_plist_ctx, 0);
    recompui_set_context_captures_mouse(s_plist_ctx, 0);
    recompui_open_context(s_plist_ctx);

    RecompuiResource root = recompui_context_root(s_plist_ctx);

    /* Panel: fixed to the top-left corner. */
    RecompuiResource panel = recompui_create_element(s_plist_ctx, root);
    recompui_set_position(panel, POSITION_ABSOLUTE);
    recompui_set_left(panel, 12.0f, UNIT_DP);
    recompui_set_top(panel, 12.0f, UNIT_DP);
    recompui_set_width(panel, PANEL_WIDTH, UNIT_DP);
    recompui_set_background_color(panel, &COLOR_BG);
    recompui_set_border_radius(panel, 6.0f, UNIT_DP);
    recompui_set_border_width(panel, 1.0f, UNIT_DP);
    recompui_set_border_color(panel, &COLOR_BORDER);
    recompui_set_padding(panel, 8.0f, UNIT_DP);
    recompui_set_flex_direction(panel, FLEX_DIRECTION_COLUMN);
    recompui_set_display(panel, DISPLAY_FLEX);

    /* "Online Players" title. */
    RecompuiResource title = recompui_create_label(
        s_plist_ctx, panel, "Online Players", LABELSTYLE_SMALL);
    recompui_set_color(title, &COLOR_GOLD);
    recompui_set_font_weight(title, 700);
    recompui_set_margin_bottom(title, 2.0f, UNIT_DP);

    /* Thin divider. */
    RecompuiResource divider = recompui_create_element(s_plist_ctx, panel);
    recompui_set_width(divider, 100.0f, UNIT_PERCENT);
    recompui_set_height(divider, 1.0f, UNIT_DP);
    recompui_set_background_color(divider, &COLOR_BORDER);
    recompui_set_margin_bottom(divider, 4.0f, UNIT_DP);

    /* Rows container: vertical flex column holding per-player rows. */
    s_plist_rows_container = recompui_create_element(s_plist_ctx, panel);
    recompui_set_display(s_plist_rows_container, DISPLAY_FLEX);
    recompui_set_flex_direction(s_plist_rows_container, FLEX_DIRECTION_COLUMN);
    recompui_set_gap(s_plist_rows_container, 4.0f, UNIT_DP);

    /* Pre-allocate MAX_DISPLAY_PLAYERS slots; all start hidden.
     * Each slot is a column: an optional team-section header on top,
     * followed by the player row.  The team header is only shown when
     * the player is the first member of a new team in the sorted list. */
    for (int i = 0; i < MAX_DISPLAY_PLAYERS; i++)
    {
        /* ── Outer slot: column layout, hidden until assigned. ─────── */
        s_plist_rows[i].row = recompui_create_element(
            s_plist_ctx, s_plist_rows_container);
        recompui_set_display(s_plist_rows[i].row, DISPLAY_NONE);
        recompui_set_flex_direction(s_plist_rows[i].row, FLEX_DIRECTION_COLUMN);

        /* ── Team section header (hidden by default). ──────────────── */
        s_plist_rows[i].team_hdr = recompui_create_element(
            s_plist_ctx, s_plist_rows[i].row);
        recompui_set_display(s_plist_rows[i].team_hdr, DISPLAY_NONE);
        recompui_set_padding_left(s_plist_rows[i].team_hdr, 2.0f, UNIT_DP);
        recompui_set_padding_top(s_plist_rows[i].team_hdr, 2.0f, UNIT_DP);
        recompui_set_padding_bottom(s_plist_rows[i].team_hdr, 4.0f, UNIT_DP);
        recompui_set_margin_top(s_plist_rows[i].team_hdr, 6.0f, UNIT_DP);
        recompui_set_border_bottom_width(s_plist_rows[i].team_hdr, 1.0f, UNIT_DP);
        recompui_set_border_bottom_color(s_plist_rows[i].team_hdr, &COLOR_BORDER);

        s_plist_rows[i].team_label = recompui_create_label(
            s_plist_ctx, s_plist_rows[i].team_hdr, "", LABELSTYLE_ANNOTATION);
        recompui_set_color(s_plist_rows[i].team_label, &COLOR_TEAM_HDR);
        recompui_set_font_weight(s_plist_rows[i].team_label, 700);

        /* ── Player row: flex-row with icon and label. ─────────────── */
        s_plist_rows[i].player_row = recompui_create_element(
            s_plist_ctx, s_plist_rows[i].row);
        recompui_set_display(s_plist_rows[i].player_row, DISPLAY_FLEX);
        recompui_set_flex_direction(s_plist_rows[i].player_row, FLEX_DIRECTION_ROW);
        recompui_set_align_items(s_plist_rows[i].player_row, ALIGN_ITEMS_CENTER);
        recompui_set_gap(s_plist_rows[i].player_row, 6.0f, UNIT_DP);
        recompui_set_padding_top(s_plist_rows[i].player_row, 2.0f, UNIT_DP);

        /* Character icon image view. */
        s_plist_rows[i].icon = recompui_create_imageview(
            s_plist_ctx, s_plist_rows[i].player_row, s_blank_texture);
        recompui_set_width(s_plist_rows[i].icon, ICON_SIZE, UNIT_DP);
        recompui_set_height(s_plist_rows[i].icon, ICON_SIZE, UNIT_DP);

        /* Player name + location label. */
        s_plist_rows[i].label = recompui_create_label(
            s_plist_ctx, s_plist_rows[i].player_row, "", LABELSTYLE_SMALL);
        recompui_set_color(s_plist_rows[i].label, &COLOR_DIM);
    }

    recompui_close_context(s_plist_ctx);
}

/* =========================================================================
   Per-frame game hook
   ========================================================================= */

RECOMP_HOOK_RETURN("func_80002040_2C40")
void anchor_ui_update(void)
{
    /* ----- One-time eager context creation --------------------------------
     * plist_ctx must be created BEFORE debug.c creates its toggle context so
     * that the toggle context sits at a higher Z-order.  recompui places
     * later-created contexts on top; if plist_ctx were created lazily (after
     * the toggle context) its root would be above the DBG/NET buttons and
     * block their mouse events even with captures_mouse = 0.
     * anchor_ui_update runs before debug_ui_frame_hook every frame (link
     * order is alphabetical), so calling plist_ensure_init() here on the
     * very first frame guarantees the correct stacking order.              */
    {
        static int s_ctx_created = 0;
        if (!s_ctx_created)
        {
            s_ctx_created = 1;
            plist_ensure_init();
        }
    }

    /* ----- Notification countdown ---------------------------------------- */
    if (s_notif_timer > 0)
    {
        s_notif_timer--;
        if (s_notif_timer == 0 && s_notif_ctx != RECOMPUI_NULL_CONTEXT)
            recompui_hide_context(s_notif_ctx);
    }

    /* Startup/race configuration screens are full-screen interactive modals.
     * Keep the player list out of the UI stack until the game has actually
     * launched so RT64 and startup menus retain control. */
    if (!anchor_startup_menu_is_complete())
    {
        if (s_plist_visible && s_plist_ctx != RECOMPUI_NULL_CONTEXT)
        {
            recompui_hide_context(s_plist_ctx);
            s_plist_visible = 0;
        }
        s_plist_refresh_timer = 0;
        return;
    }

    /* ----- Player list maintenance --------------------------------------- */
    if (!anchor_is_connected())
    {
        if (s_plist_visible && s_plist_ctx != RECOMPUI_NULL_CONTEXT)
        {
            recompui_hide_context(s_plist_ctx);
            s_plist_visible = 0;
        }
        s_plist_refresh_timer = 0;
        return;
    }

    /* Ensure context exists the first time we are connected. */
    plist_ensure_init();

    /* Throttle refresh to once per PLAYER_LIST_REFRESH_FRAMES frames. */
    if (s_plist_refresh_timer > 0)
    {
        s_plist_refresh_timer--;
        return;
    }
    s_plist_refresh_timer = PLAYER_LIST_REFRESH_FRAMES;

    /* Fetch structured player info from Python:
     * [{"n":"Name - Location","c":0,"r":165,"t":"default","hp":1,"x":10,"y":20,"z":30}, ...]
     * where "c" is the character index (0=Goemon..3=Yae, -1=unknown). */
    char *info_json = anchor_get_player_info_json();
    if (!info_json)
        return;

    /* Parse info_json into local row data arrays (no JSON library needed:
     * the format is fixed and machine-generated).
     * Python already sorts entries by (teamId, clientId). */
    static char row_name_buf[MAX_DISPLAY_PLAYERS][128];
    static char row_team_buf[MAX_DISPLAY_PLAYERS][40]; /* team ID string, may be empty */
    static int row_char_idx[MAX_DISPLAY_PLAYERS];
    static int row_room_id[MAX_DISPLAY_PLAYERS]; /* raw 16-bit room ID, -1 = unknown */
    static int row_has_pos[MAX_DISPLAY_PLAYERS];
    static int row_pos_x[MAX_DISPLAY_PLAYERS];
    static int row_pos_y[MAX_DISPLAY_PLAYERS];
    static int row_pos_z[MAX_DISPLAY_PLAYERS];
    int row_count = 0;
    const char *p = info_json;

    while (*p && row_count < MAX_DISPLAY_PLAYERS)
    {
        /* Locate the "n":" key. */
        while (*p && !(*p == '"' && *(p + 1) == 'n' && *(p + 2) == '"' && *(p + 3) == ':' && *(p + 4) == '"'))
            p++;
        if (!*p)
            break;
        p += 5; /* skip "n":" */

        /* Read name string until the closing quote (honour \" escapes). */
        int n = 0;
        while (*p && *p != '"' && n < (int)sizeof(row_name_buf[0]) - 1)
        {
            if (*p == '\\' && *(p + 1))
                p++; /* skip escape prefix */
            row_name_buf[row_count][n++] = *p++;
        }
        row_name_buf[row_count][n] = '\0';
        if (*p == '"')
            p++;

        /* Locate the "c": key. */
        while (*p && !(*p == '"' && *(p + 1) == 'c' && *(p + 2) == '"' && *(p + 3) == ':'))
            p++;
        if (!*p)
            break;
        p += 4; /* skip "c": */

        /* Read integer value (may be negative for -1). */
        int sign = 1;
        if (*p == '-')
        {
            sign = -1;
            p++;
        }
        int cidx = 0;
        while (*p >= '0' && *p <= '9')
            cidx = cidx * 10 + (*p++ - '0');
        row_char_idx[row_count] = cidx * sign;

        /* Locate the "r": key (raw room ID). */
        row_room_id[row_count] = -1;
        {
            const char *q = p;
            while (*q && !(*q == '"' && *(q + 1) == 'r' && *(q + 2) == '"' && *(q + 3) == ':'))
                q++;
            if (*q)
            {
                q += 4; /* skip "r": */
                int rsign = 1;
                if (*q == '-')
                {
                    rsign = -1;
                    q++;
                }
                int rid = 0;
                while (*q >= '0' && *q <= '9')
                    rid = rid * 10 + (*q++ - '0');
                row_room_id[row_count] = rid * rsign;
            }
        }

        row_has_pos[row_count] = parse_json_int_field(p, 'h', 'p', 2, 0);
        row_pos_x[row_count] = parse_json_int_field(p, 'x', '\0', 1, 0);
        row_pos_y[row_count] = parse_json_int_field(p, 'y', '\0', 1, 0);
        row_pos_z[row_count] = parse_json_int_field(p, 'z', '\0', 1, 0);

        /* Locate the "t":" key (team ID string). */
        row_team_buf[row_count][0] = '\0';
        {
            const char *q = p;
            while (*q && !(*q == '"' && *(q + 1) == 't' && *(q + 2) == '"' && *(q + 3) == ':' && *(q + 4) == '"'))
                q++;
            if (*q)
            {
                q += 5; /* skip "t":" */
                int tn = 0;
                while (*q && *q != '"' && tn < (int)sizeof(row_team_buf[0]) - 1)
                {
                    if (*q == '\\' && *(q + 1))
                        q++;
                    row_team_buf[row_count][tn++] = *q++;
                }
                row_team_buf[row_count][tn] = '\0';
            }
        }

        row_count++;
    }

    recomp_free(info_json);

    /* Read config options once per refresh. */
    int show_room_hex = (recomp_get_config_u32("anchor_show_room_hex") == 0);
    int show_positions = (recomp_get_config_u32("anchor_show_player_positions") == 0);

    static const char s_hex_chars[] = "0123456789ABCDEF";
    static char label_buf[PLAYER_LABEL_BUF_LEN];

    recompui_open_context(s_plist_ctx);
    for (int i = 0; i < row_count; i++)
    {
        /* ── Determine if a new team section starts at this slot. ────── */
        int new_team = (i == 0);
        if (!new_team)
        {
            const char *a = row_team_buf[i], *b = row_team_buf[i - 1];
            while (*a && *b && *a == *b)
            {
                ++a;
                ++b;
            }
            if (*a != *b)
                new_team = 1;
        }

        /* Show the outer slot (column wrapper). */
        recompui_set_display(s_plist_rows[i].row, DISPLAY_FLEX);

        /* Team section header – visible only for the first player of each team. */
        if (new_team)
        {
            const char *tname = row_team_buf[i][0] ? row_team_buf[i] : "default";
            recompui_set_text(s_plist_rows[i].team_label, tname);
            recompui_set_display(s_plist_rows[i].team_hdr, DISPLAY_FLEX);
        }
        else
        {
            recompui_set_display(s_plist_rows[i].team_hdr, DISPLAY_NONE);
        }

        /* Character icon. */
        int ci = row_char_idx[i];
        RecompuiTextureHandle tex =
            (ci >= 0 && ci < 4) ? s_char_textures[ci] : s_blank_texture;
        recompui_set_imageview_texture(s_plist_rows[i].icon, tex);

        /* Player label, optionally with room and position details appended. */
        {
            int len = 0;
            const char *src = row_name_buf[i];
            while (*src && len < 127)
                label_buf[len++] = *src++;

            if (show_room_hex && row_room_id[i] >= 0)
            {
                append_text_limited(label_buf, &len, PLAYER_LABEL_BUF_LEN, " (0x");
                unsigned int rid = (unsigned int)row_room_id[i];
                append_char_limited(label_buf, &len, PLAYER_LABEL_BUF_LEN, s_hex_chars[(rid >> 12) & 0xF]);
                append_char_limited(label_buf, &len, PLAYER_LABEL_BUF_LEN, s_hex_chars[(rid >> 8) & 0xF]);
                append_char_limited(label_buf, &len, PLAYER_LABEL_BUF_LEN, s_hex_chars[(rid >> 4) & 0xF]);
                append_char_limited(label_buf, &len, PLAYER_LABEL_BUF_LEN, s_hex_chars[rid & 0xF]);
                append_char_limited(label_buf, &len, PLAYER_LABEL_BUF_LEN, ')');
            }

            if (show_positions && row_has_pos[i])
            {
                append_text_limited(label_buf, &len, PLAYER_LABEL_BUF_LEN, " [");
                append_int_limited(label_buf, &len, PLAYER_LABEL_BUF_LEN, row_pos_x[i]);
                append_text_limited(label_buf, &len, PLAYER_LABEL_BUF_LEN, ", ");
                append_int_limited(label_buf, &len, PLAYER_LABEL_BUF_LEN, row_pos_y[i]);
                append_text_limited(label_buf, &len, PLAYER_LABEL_BUF_LEN, ", ");
                append_int_limited(label_buf, &len, PLAYER_LABEL_BUF_LEN, row_pos_z[i]);
                append_char_limited(label_buf, &len, PLAYER_LABEL_BUF_LEN, ']');
            }

            label_buf[len] = '\0';
            recompui_set_text(s_plist_rows[i].label, label_buf);
        }
    }
    /* Hide any slots beyond the current player count. */
    for (int i = row_count; i < MAX_DISPLAY_PLAYERS; i++)
        recompui_set_display(s_plist_rows[i].row, DISPLAY_NONE);
    recompui_close_context(s_plist_ctx);

    /* Show the panel the first time we have data (also handles reconnect
     * after a disconnect, since s_plist_visible is cleared on hide).        */
    if (!s_plist_visible)
    {
        recompui_show_context(s_plist_ctx);
        s_plist_visible = 1;
        /* recompui_show_context bumps s_plist_ctx to the top of the Z-stack;
         * immediately re-raise the toggle-button context so DBG/NET buttons
         * are always above the player-list panel and remain clickable.      */
        debug_ui_bump_toggle_ctx();
    }
}

