            draw->mode = 5;
            draw->material = 1;
        }
        else
        {
            static const unsigned int textures[] = {
                0x0a007980u, 0x0a008180u, 0x0a013980u, 0x0a014180u,
                0x0a014980u, 0x0a015180u, 0x0a015980u, 0x0a016180u
